<span class="line"><span style="color:#C678DD;">    return</span><span style="color:#ABB2BF;"> Y.</span><span style="color:#61AFEF;">reshape</span><span style="color:#ABB2BF;">(Y.shape[</span><span style="color:#D19A66;">2</span><span style="color:#ABB2BF;">:])</span></span>
